import '../models/injury_report.dart';

/// يبني تقرير HTML لتحقيق إصابة عمل (QMS-SAF-007) — نسخة طبق الأصل من
/// استمارة الوورد الرسمية "تقرير تحقيق بالحادث" التي اعتمدها العميل، بنفس
/// حقولها وترتيبها وصياغتها الثنائية اللغة بالضبط (سطر إنجليزي أولًا، ثم
/// سطر عربي منفصل تحته لكل قسم من أقسام الاختيار المتعدد — إلا قسم "This
/// employee works" فهو عمودان جنبًا إلى جنب كما في الاستمارة الأصلية)، وبنفس
/// اتجاهها الأساسي من اليسار لليمين (استمارة إنجليزية أساسًا مع ترجمة عربية
/// تحت كل عنصر) ونفس رسوماتها الثابتة (الشعار، مخطط الجسم، مخطط عظمة
/// السمكة، هرم هرمية الضوابط الملون) ونفس مقاس الورق (Letter).
///
/// ملاحظات مهمة عن بعض الاختلافات عن النسخة الورقية (بحسب توجيه العميل):
/// 1) مكان الإصابة على مخطط الجسم يُعلَّم تلقائيًا بدائرة حمراء (بدل التظليل
///    اليدوي) فوق كل جزء مُدخَل في التطبيق — راجع خريطة bodyMarks أدناه؛ يبقى
///    السطر النصي أسفل الرسم أيضًا كملخص واضح لنفس المعلومة.
/// 2) خانة "Sign" في جدول CAR/PAR وخانة "Signature" النهائية تُتركان فارغتين
///    عمدًا (بدون أي علامة أو اسم) ليوقّعهما المسؤول يدويًا على الورق بعد
///    طباعة التقرير، بناءً على طلب العميل صراحة.
/// 3) حقل "التاريخ" المرافق لـ"Written by" لا يوجد له حقل مطابق صريح في
///    النظام، فاستُخدم تاريخ التحقيق (investigationDate) كأقرب قيمة منطقية.
/// 4) نص شارات الخطوات الإنجليزية مكتوب بترتيبه الصحيح (مثال: "Step 1:
///    Employee Injured") — الاستمارة الأصلية كانت تحمل خطأ مطبعيًا بترتيب
///    الكلمات معكوسًا في هذه الشارات تحديدًا، وصحّحناه بناءً على طلب العميل.
String buildInjuryReportHtml(InjuryReport r) {
   const chk = '<b style="font-size:14px; color:#000;">✔</b>';
  const unchk = '☐';

  const logoB64 = '';
  const bodyDiagramB64 = '';
  const fishboneB64 = '';

  String esc(String? s) {
    if (s == null) return '';
    return s.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  }

  String two(int n) => n.toString().padLeft(2, '0');

  String fmtDate(DateTime? d) {
    if (d == null) return '';
    return '${d.year}/${two(d.month)}/${two(d.day)}';
  }

  String fmtTime(DateTime? d) {
    if (d == null) return '';
    var h = d.hour % 12;
    if (h == 0) h = 12;
    final period = d.hour >= 12 ? 'PM' : 'AM';
    return '${two(h)}:${two(d.minute)} $period';
  }

  String yesNoEn(bool? v) => v == null ? '—' : (v ? 'Yes' : 'No');
  String yesNoAr(bool? v) => v == null ? '—' : (v ? 'نعم' : 'لا');

  // كل عنصر: (المفتاح المخزَّن في القاعدة، النص الإنجليزي، النص العربي) —
  // بنفس الترتيب الحرفي للخانات في الاستمارة الأصلية ونفس القوائم في
  // routes/injuryReports.js (يجب أن تبقى متطابقة بين الطرفين).
  const natureOfAccidentOptions = <(String, String, String)>[
    ('near_miss', 'Near miss', 'خطر كامن وشيك الحدوث'),
    ('injury_illness', 'Injury/Illness', 'إصابة/مرض'),
    ('fire', 'Fire', 'حريق'),
    ('leakage', 'Leakage', 'تسريب'),
    ('property_damage', 'Property Damage', 'ضرر في الممتلكات'),
    ('vehicle_accident', 'Vehicle Accident', 'حادث سيارة'),
    ('explosion', 'Explosion', 'انفجار'),
  ];
  const injuryTypeOptions = <(String, String, String)>[
    ('medical_treatment', 'Injury/Illness (Medical Treatment)', 'إصابة/مرض (نقل الى المستشفى)'),
    ('first_aid', 'Injury/Illness (First Aid)', 'إصابة/مرض (اسعافات أولية)'),
    ('lost_time', 'Injury/Illness (Lost Time Case "Day off")', 'إصابة/مرض (وقت إجازة)'),
    ('fatality', 'Fatality', 'وفاة'),
  ];
  const workdayPartOptions = <(String, String, String)>[
    ('normal_activities', 'Doing normal work activities', 'أثناء القيام بأعمال اعتيادية'),
    ('entering_leaving', 'Entering or leaving work', 'أثناء الدخول أو الخروج'),
    ('meal_period', 'During meal period', 'أثناء فترة تناول الطعام'),
    ('break', 'During break', 'أثناء وقت الاستراحة'),
    ('overtime', 'Working overtime', 'أثناء العمل الإضافي'),
    ('other', 'Other', 'أخرى'),
  ];
  const ppeUsedOptions = <(String, String, String)>[
    ('helmet', 'Helmet', 'خوذة السلامة'),
    ('safety_shoes', 'Safety Shoes', 'حذاء السلامة'),
    ('earplugs', 'Earplugs', 'سدادات الأذن'),
    ('earmuffs', 'Earmuffs', 'غطاء الأذن'),
    ('glasses', 'Glasses', 'نظارات'),
    ('face_protection', 'Face protection', 'واقي الوجه'),
    ('gloves', 'Gloves', 'قفازات'),
    ('dust_mask', 'Dust mask', 'قناع الغبار'),
    ('full_body_harness', 'Full body harness', 'حزام الجسم الكامل'),
  ];
  const injuryNatureOptions = <(String, String, String)>[
    ('abrasion', 'Abrasion', 'خدوش'),
    ('amputation', 'Amputation', 'بتر'),
    ('broken_bone', 'Broken bone', 'كسر بالعظم'),
    ('bruise', 'Bruise', 'رضوض وكدمات'),
    ('burn_heat', 'Burn (heat)', 'حروق بالحرارة'),
    ('burn_chemical', 'Burn (chemical)', 'حروق بمواد كيميائية'),
    ('burn_fire', 'Burn (fire)', 'حروق بالنار'),
    ('concussion', 'Concussion (to the head)', 'ارتجاج بالرأس'),
    ('cut_laceration_puncture', 'Cut, laceration, puncture', 'قطع، تمزق، ثقب'),
    ('hernia', 'Hernia', 'فتق'),
    ('sprain', 'Sprain', 'التواء'),
    ('body_system_damage', 'Damage to a body system', 'أضرار بأنظمة الجسم'),
    ('other', 'Other', 'أخرى'),
  ];
  const employmentTypeOptions = <(String, String, String)>[
    ('full_time', 'Regular full time', 'موظف منتظم بدوام كامل'),
    ('part_time', 'Regular part time', 'موظف منتظم بدوام جزئي'),
    ('seasonal', 'Seasonal', 'موظف بدوام فصلي'),
    ('temporary', 'Temporary', 'موظف مؤقت'),
    ('contractor', 'Contractor', 'متعاقد'),
  ];
  const preventionChangeOptions = <(String, String, String)>[
    ('stop_activity', 'Stop this activity', 'إيقاف هذا النشاط'),
    ('guard_hazard', 'Guard the hazard', 'حراسة الخطر'),
    ('train_employees', 'Train the employee(s)', 'تدريب الموظفين'),
    ('train_supervisors', 'Train the supervisor(s)', 'تدريب المشرفين'),
    ('redesign_task', 'Redesign task steps', 'إعادة تصميم خطوات المهمة'),
    ('redesign_workstation', 'Redesign work station', 'إعادة تصميم محطة العمل'),
    ('new_policy', 'Write a new policy/rule', 'كتابة سياسة/قانون جديد'),
    ('enforce_policy', 'Enforce existing policy', 'فرض السياسة القائمة'),
    ('routine_inspection', 'Routinely inspect for the hazard', 'التفتيش الدوري عن المخاطر'),
    ('use_ppe', 'Use Personal Protective Equipment', 'استخدام أدوات الحماية الشخصية'),
    ('other', 'Other', 'أخرى'),
  ];
  const bodyPartLabels = <String, String>{
    'head': 'الرأس', 'face': 'الوجه', 'eye': 'العين', 'neck': 'الرقبة', 'shoulder': 'الكتف',
    'arm': 'الذراع', 'elbow': 'المرفق', 'wrist': 'المعصم', 'hand_fingers': 'اليد / الأصابع',
    'chest': 'الصدر', 'back': 'الظهر', 'abdomen': 'البطن', 'pelvis': 'الحوض', 'thigh': 'الفخذ',
    'knee': 'الركبة', 'leg': 'الساق', 'ankle': 'الكاحل', 'foot_toes': 'القدم / أصابع القدم', 'other': 'أخرى',
  };
  const hierarchyOptions = <(String, String, String)>[
    ('elimination', 'Elimination', '#b03a2e'),
    ('substitution', 'Substitution', '#3498a5'),
    ('engineering_control', 'Engineering control', '#7d5aa6'),
    ('administrative_control', 'Administrative control', '#2ea86b'),
    ('ppe', 'Provide PPE', '#2470b8'),
  ];

  // إحداثيات تقريبية (نسبة % من عرض/ارتفاع صورة مخطط الجسم الأصلية 360×422)
  // لوضع دائرة حمراء تلقائيًا على مكان كل إصابة مُدخَلة بدل التظليل اليدوي —
  // بما أن جهة الإصابة (يمين/يسار) غير مسجَّلة في النظام، توضع دائرة على
  // الجانبين معًا (وعلى الرسمين الأمامي والخلفي لو الجزء ظاهر فيهما) لتغطية
  // الاحتمالين. "other" بلا موضع محدد فيبقى في السطر النصي أسفل الرسم فقط.
  const bodyMarks = <String, List<(double, double)>>{
    'head': [(26.4, 8.3), (80.6, 8.3)],
    'face': [(26.4, 13.0)],
    'eye': [(26.4, 11.8)],
    'neck': [(26.4, 19.0), (80.6, 19.0)],
    'shoulder': [(15.3, 28.4), (38.1, 28.4), (69.4, 28.4), (91.7, 28.4)],
    'arm': [(13.3, 40.8), (40.3, 40.8), (68.1, 40.8), (93.1, 40.8)],
    'elbow': [(9.7, 47.9), (43.1, 47.4), (64.4, 47.9), (96.7, 47.4)],
    'wrist': [(5.6, 54.0), (46.7, 52.1), (57.8, 54.0), (97.8, 52.1)],
    'hand_fingers': [(2.2, 58.8), (50.6, 57.3), (54.4, 58.8), (99.0, 57.3)],
    'chest': [(26.4, 35.5)],
    'back': [(80.6, 37.9)],
    'abdomen': [(26.4, 46.2)],
    'pelvis': [(26.4, 51.7), (80.6, 51.7)],
    'thigh': [(20.8, 64.0), (31.9, 64.0), (75.0, 64.0), (86.1, 64.0)],
    'knee': [(20.8, 71.1), (31.9, 71.1), (75.0, 71.1), (86.1, 71.1)],
    'leg': [(21.7, 78.2), (31.1, 78.2), (75.6, 78.2), (85.6, 78.2)],
    'ankle': [(22.2, 87.7), (30.6, 87.7), (76.4, 87.7), (84.7, 87.7)],
    'foot_toes': [(20.8, 93.6), (31.9, 93.6), (75.0, 93.6), (86.1, 93.6)],
  };

  String bodyDiagramWithMarks(List<String> bodyLabels) {
    final marksHtml = StringBuffer();
    for (final k in bodyLabels) {
      for (final pt in bodyMarks[k] ?? const <(double, double)>[]) {
        marksHtml.write('<div class="body-mark" style="left:${pt.$1}%; top:${pt.$2}%;"></div>');
      }
    }
    return '<div class="body-diagram-wrap"><img src="data:image/jpeg;base64,$bodyDiagramB64" />$marksHtml</div>';
  }

  String chkLineEn(List<(String, String, String)> options, List<String> selected, {String? otherText, String otherKey = 'other'}) {
    final items = options.map((o) {
      final mark = selected.contains(o.$1) ? chk : unchk;
      var txt = '$mark${esc(o.$2)}';
      if (o.$1 == otherKey) {
        txt += (otherText != null && otherText.isNotEmpty) ? '……${esc(otherText)}' : '……………………';
      }
      return txt;
    }).join(' &nbsp; ');
    return '<div class="chk-line en">$items</div>';
  }

  String chkLineAr(List<(String, String, String)> options, List<String> selected, {String? otherText, String otherKey = 'other'}) {
    final items = options.map((o) {
      final mark = selected.contains(o.$1) ? chk : unchk;
      var txt = '$mark${esc(o.$3)}';
      if (o.$1 == otherKey) {
        txt += (otherText != null && otherText.isNotEmpty) ? '……${esc(otherText)}' : '……………………';
      }
      return txt;
    }).join(' &nbsp; ');
    return '<div class="chk-line ar">$items</div>';
  }

  String lbl(String en, String ar) => '${esc(en)}<br/><span class="ar">${esc(ar)}</span>';

  String headerBlock() => '''
    <table class="hdr-table">
      <tr>
        <td class="hdr-logo"><img src="data:image/png;base64,$logoB64" /></td>
        <td class="hdr-title">
          <div class="hdr-title-en">INCIDENT INVESTIGATION REPORT</div>
          <div class="hdr-title-ar ar">تقرير تحقيق بالحادث</div>
        </td>
        <td class="hdr-qms">
          <div>QMS-SAF-007</div>
          <div>REV:001</div>
          <div>ISSUE DATE:20/01/2026</div>
        </td>
      </tr>
    </table>
  ''';

  // ملاحظة: نص الخطوات الإنجليزي أدناه منسوخ حرفيًا (بترتيبه المعكوس) من
  // استمارة الوورد الأصلية — راجع تعليق أعلى الدالة.
  String stepBanner(String enLiteral, String ar) =>
      '<div class="step-banner"><span>${esc(enLiteral)}</span><span class="ar">${esc(ar)}</span></div>';

  String pageHeaderSection() => '''
    ${headerBlock()}
    <table class="form-table">
      <tr>
        <td class="lbl" style="width:16%">${lbl('Number of incidents', 'رقم الحادث')}</td>
        <td style="width:14%">${esc(r.incidentNumber != null && r.incidentNumber!.isNotEmpty ? r.incidentNumber : '#${r.id}')}</td>
        <td class="lbl" style="width:14%">${lbl('Dept./Section', 'القسم/الإدارة')}</td>
        <td style="width:20%" class="ar">${esc(r.department)}</td>
        <td class="lbl" style="width:16%">${lbl('Date of investigation', 'تاريخ التحقيق')}</td>
