    ${headerBlock()}
    ${stepBanner('Step 2: Describe the Incident', 'الخطوة الثانية: وصف الحادث')}
    <table class="form-table">
      <tr>
        <td class="lbl" style="width:20%">${lbl('Exact location of the Incident', 'موقع الحادث')}</td>
        <td class="ar" style="width:26%">${esc(r.incidentLocation)}</td>
        <td class="lbl" style="width:14%">${lbl('Date of incident', 'تاريخ الحادث')}</td>
        <td style="width:16%">${fmtDate(r.occurredAt)}</td>
        <td class="lbl" style="width:12%">${lbl('Time of incident', 'وقت الحادث')}</td>
        <td style="width:12%">${fmtTime(r.occurredAt)}</td>
