        <td colspan="5">${chkLineAr(workdayPartOptions, workday, otherText: r.workdayPartOther)}</td>
      </tr>
      <tr>
        <td class="lbl">${lbl('Written witness statements', 'خطابات الشهود المكتوبة')}</td>
        <td>${yesNoEn(r.witnessStatements)} / <span class="ar">${yesNoAr(r.witnessStatements)}</span></td>
        <td class="lbl">${lbl('Photographs', 'الصور')}</td>
        <td>${yesNoEn(r.photographsTaken)} / <span class="ar">${yesNoAr(r.photographsTaken)}</span></td>
        <td class="lbl">${lbl('Maps / drawings', 'الرسوم والمخططات')}</td>
        <td>${yesNoEn(r.mapsDrawings)} / <span class="ar">${yesNoAr(r.mapsDrawings)}</span></td>
      </tr>
      <tr>
        <td class="lbl" colspan="6">What personal protective equipment was being used during the accident?</td>
