      <tr><td colspan="6">${chkLineEn(ppeUsedOptions, r.ppeUsed)}</td></tr>
      <tr><td class="lbl ar" colspan="6">ما أدوات الحماية الشخصية التي استُخدمت أثناء الحادث؟</td></tr>
      <tr><td colspan="6">${chkLineAr(ppeUsedOptions, r.ppeUsed)}</td></tr>
      <tr>
        <td class="lbl" colspan="6">Describe, step-by-step the events that led up to the accident or injury. Include names of any machines, parts, objects, tools, materials and other important details:<br/>
        <span class="ar">صف، خطوة بخطوة الأحداث التي قادت إلى الحادث أو الإصابة. أضف أسماء أي آلة وقطع الغيار والمعدات وأي تفاصيل أخرى هامة.</span></td>
      </tr>
      <tr>
        <td class="lbl" colspan="6" style="text-align:center">Description of the incident — <span class="ar">وصف الحادثة</span></td>
      </tr>
      <tr>
        <td colspan="6" class="big-text ar">${esc(r.incidentDescription)}</td>
      </tr>
    </table>
  ''';
  }

  String pageFishbone() => '''
    ${headerBlock()}
    <div class="step3-title"><span>Step 3: Why did the Incident happen?</span><span class="ar">الخطوة الثالثة: ما سبب حدوث الحادث؟</span></div>
    <div class="fishbone"><img src="data:image/jpeg;base64,$fishboneB64" /></div>
  ''';

  String pageWhy() => '''
    ${headerBlock()}
    <table class="form-table">
      <tr><td class="lbl" style="width:30%">Why did the unsafe conditions exist?<br/><span class="ar">ما سبب وجود هذه الظروف الغير أمنة؟</span></td>
          <td class="big-text ar">${esc(r.unsafeConditionReason)}</td></tr>
      <tr><td class="lbl">Why did the unsafe acts occur?<br/><span class="ar">ما سبب حدوث هذه التصرفات الغير أمنة؟</span></td>
          <td class="big-text ar">${esc(r.unsafeActReason)}</td></tr>
      <tr>
        <td class="lbl">Is there a reward (such as "the job can be done more quickly" or "the product is less likely to be damaged") that may have encouraged the unsafe conditions or acts?<br/>
        <span class="ar">هل هناك مكافأة )مثال: لو تم إنجاز العمل بسرعة أو تقليل تعرض المنتج ألي تلفيات( قد تشجع على حدوث الظروف والأفعال الغير آمنة؟</span></td>
        <td>${yesNoEn(r.hadRewardIncentive)} / <span class="ar">${yesNoAr(r.hadRewardIncentive)}</span></td>
      </tr>
      <tr>
        <td class="lbl">Were the unsafe acts or conditions reported prior to the Incident?<br/><span class="ar">هل الظروف أو الأفعال الغير أمنة تم إعداد تقرير عنها مسبقاً قبل حدوث الحادث؟</span></td>
        <td>${yesNoEn(r.reportedBefore)} / <span class="ar">${yesNoAr(r.reportedBefore)}</span></td>
      </tr>
      <tr>
        <td class="lbl">Have there been similar Incidents or near misses prior to this one?<br/><span class="ar">هل كان هناك حوادث أو أخطار كامنة الحدوث مماثلة لهذا الحادث؟</span></td>
        <td>${yesNoEn(r.similarIncidentsBefore)} / <span class="ar">${yesNoAr(r.similarIncidentsBefore)}</span></td>
      </tr>
    </table>
  ''';

  String pageHierarchy() {
    final selectedKey = r.hierarchyOfControl;
    final rows = hierarchyOptions.map((h) {
      final details = h.$1 == selectedKey ? esc(r.controlDetails) : '';
      return '''
          <tr>
            <td class="hoc-cell"><span class="hoc-label">${h.$2}</span><div class="triangle" style="border-top-color:${h.$3}"></div></td>
            <td class="hoc-details ar">$details</td>
          </tr>''';
    }).join();
    return '''
    ${headerBlock()}
    <table class="form-table hoc-table">
      <tr><td class="lbl" style="text-align:center;width:55%">Hierarchy of Controls</td><td class="lbl" style="text-align:center">Details of selected control</td></tr>
      $rows
    </table>
    <table class="form-table" style="margin-top:6px">
      <tr><td class="lbl" colspan="2">What changes must be done to prevent this Incident/near miss from happening again?<br/><span class="ar">ما هي التغييرات التي يجب أن تحدث لمنع/الوقاية من حوادث أو أخطار كامنة الحدوث مرة أخرى؟</span></td></tr>
      <tr><td colspan="2">${chkLineEn(preventionChangeOptions, r.preventionChanges, otherText: r.preventionChangesOther)}</td></tr>
      <tr><td colspan="2" class="ar">${chkLineAr(preventionChangeOptions, r.preventionChanges, otherText: r.preventionChangesOther)}</td></tr>
      <tr><td class="lbl" colspan="2">What should be (or has been) done to carry out the action(s) checked above? And what Should be done to prevent this Injury/near miss?<br/>
      <span class="ar">ما الذي يجب أو يمكن تنفيذه لتحقيق الإجراءات التي حددت بالأعلى؟ ومالذي يجب عمله لمنع حدوث هذه الإصابة / والوقاية من هذا الخطر الكامن؟</span></td></tr>
      <tr><td colspan="2" class="big-text ar">${esc(r.preventionNotes)}</td></tr>
    </table>
  ''';
  }

  String pageActionsSignoff() {
    final actionRows = StringBuffer();
    for (final a in r.actions) {
      actionRows.write('''<tr>
          <td class="ar">${esc(a.actionDescription)}</td>
          <td class="ar">${esc(a.responsiblePerson)}</td>
          <td class="center"></td>
          <td>${fmtDate(a.targetDate)}</td>
        </tr>''');
    }
    for (var i = r.actions.length; i < 5; i++) {
      actionRows.write('<tr><td>&nbsp;</td><td></td><td></td><td></td></tr>');
    }

    final invRows = StringBuffer();
    final invCount = r.investigators.length > 3 ? r.investigators.length : 3;
    for (var i = 0; i < invCount; i++) {
      final inv = i < r.investigators.length ? r.investigators[i] : null;
      invRows.write('''<tr>
          <td class="num-cell">${i + 1}</td>
          <td class="ar">${esc(inv?.name)}</td>
          <td class="lbl">Job title</td>
          <td class="ar">${esc(inv?.jobTitle)}</td>
        </tr>''');
    }

    return '''
    ${headerBlock()}
    <div class="car-title">Details of CAR/PAR (……) with Timeline and Responsibility</div>
    <table class="form-table car-table">
      <tr><td class="lbl center">Action</td><td class="lbl center">Responsibility</td><td class="lbl center">Sign</td><td class="lbl center">Timeline</td></tr>
      $actionRows
    </table>

    ${stepBanner('Step 5: Who completed and reviewed this form?', 'الخطوة الخامسة: من تمت مراجعة هذا وإكماله؟')}
    <table class="form-table">
      <tr>
        <td class="lbl">${lbl('Written by', 'كتب التقرير بواسطة')}</td><td class="ar">${esc(r.writtenBy)}</td>
        <td class="lbl">${lbl('Job title', 'المسمى الوظيفي')}</td><td class="ar">${esc(r.writtenByTitle)}</td>
        <td class="lbl">${lbl('Date', 'التاريخ')}</td><td>${fmtDate(r.investigationDate)}</td>
      </tr>
      <tr><td class="lbl" colspan="6">Names of investigation team members — <span class="ar">أسماء فريق التحقيق</span></td></tr>
      $invRows
      <tr>
        <td class="lbl">${lbl('Approved by', 'تم الاعتماد بواسطة')}</td><td class="ar" colspan="2">${esc(r.approvedBy)}</td>
        <td class="lbl">${lbl('Job title', 'المسمى الوظيفي')}</td><td class="ar" colspan="2">${esc(r.approvedByTitle)}</td>
      </tr>
      <tr>
        <td class="lbl">${lbl('Signature', 'التوقيع')}</td><td class="ar" colspan="2">&nbsp;</td>
        <td class="lbl">${lbl('Date', 'التاريخ')}</td><td colspan="2">${fmtDate(r.approvedAt)}</td>
      </tr>
    </table>
  ''';
  }

  const css = '''
    @page { size: letter; margin: 0; }
    * { box-sizing: border-box; }
    html { direction: ltr; }
    body { margin:0; font-family:'IBM Plex Sans Arabic','Segoe UI',Tahoma,Arial,sans-serif; color:#111; direction:ltr; }
    .ar { direction: rtl; text-align: right; unicode-bidi: isolate; }
    .page {
      width: 8.5in; height: 11in; padding: 0.35in 0.4in;
      page-break-after: always; position: relative;
      border: 3px double #000; box-sizing: border-box;
    }
    .page:last-child { page-break-after: auto; }
    .page-inner { padding: 6px 10px; height: 100%; }

    table { border-collapse: collapse; width: 100%; }
    .hdr-table { border: 1.5px solid #000; margin-bottom: 8px; }
    .hdr-table td { border: 1.5px solid #000; padding: 4px 8px; vertical-align: middle; }
    .hdr-logo { width: 100px; text-align:center; }
    .hdr-logo img { width: 78px; }
    .hdr-title { text-align:center; }
    .hdr-title-en { font-weight:700; font-size: 15px; }
    .hdr-title-ar { font-size: 14px; margin-top:2px; }
    .hdr-qms { width: 160px; font-weight:700; font-size: 11px; line-height:1.5; text-align:left; }

    .step-banner {
      background:#000; color:#fff; font-weight:700; font-size:12px;
      display:flex; justify-content:space-between; align-items:center; padding:4px 10px; margin: 6px 0 2px;
    }
    .step3-title { display:flex; justify-content:space-between; font-weight:700; font-size:12px; margin:6px 2px; }

    .form-table { border: 1.3px solid #000; font-size: 10px; margin-bottom:4px; }
    .form-table td { border: 1px solid #000; padding: 3px 6px; vertical-align: middle; overflow-wrap: break-word; }
    .lbl { font-weight:700; background:#eeeeee; }
    .yellow-row td { background:#fff3b0; }
    .center { text-align:center; }
    .big-text { min-height: 70px; vertical-align:top; white-space:pre-wrap; line-height:1.6; }

    .chk-line { font-size: 10px; line-height: 1.7; }
    .chk-line.en { text-align:left; direction:ltr; }
    .chk-line.ar { text-align:right; direction:rtl; }
    .chk-line.stacked { display:flex; flex-direction:column; gap:2px; }

    .body-diagram-wrap { position:relative; display:inline-block; margin: 4px auto; text-align:center; }
    .body-diagram-wrap img { height: 170px; display:block; margin:0 auto; }
    .body-mark { position:absolute; width:12px; height:12px; margin:-6px 0 0 -6px; border:2px solid #c0392b; border-radius:50%; background:rgba(192,57,43,0.12); }
    .body-affected-list { font-size: 9.6px; text-align:center; padding: 0 4px; }

    .fishbone { text-align:center; margin-top: 10px; }
    .fishbone img { width: 100%; }

    .hoc-table td { height: 66px; }
    .hoc-cell { display:flex; align-items:center; gap:14px; padding-left: 16px !important; }
    .triangle { width:0; height:0; border-left:32px solid transparent; border-right:32px solid transparent; border-top:42px solid; flex-shrink:0; }
    .hoc-label { font-weight:700; font-size:12px; }
    .hoc-details { vertical-align: top; padding-top:6px !important; }

    .car-title { font-weight:700; text-align:center; margin: 14px 0 6px; font-size: 12px; }
    .car-table td { height: 22px; font-size: 10px; }
    .num-cell { width: 26px; text-align:center; font-weight:700; }
  ''';

  final employees = r.employees.isEmpty ? [InjuryReportEmployee(employeeName: '—')] : r.employees;
  final fatalities = r.employees.where((e) => e.isFatality).length;
  final empPagesBuffer = StringBuffer();
  for (var i = 0; i < employees.length; i++) {
    final section = i == 0 ? pageHeaderSection() : headerBlock();
    empPagesBuffer.write('<div class="page"><div class="page-inner">$section${employeeBlock(employees[i], employees.length, fatalities)}</div></div>');
  }

  final pages = [
    empPagesBuffer.toString(),
    '<div class="page"><div class="page-inner">${pageStep2()}</div></div>',
    '<div class="page"><div class="page-inner">${pageFishbone()}</div></div>',
    '<div class="page"><div class="page-inner">${pageWhy()}</div></div>',
    '<div class="page"><div class="page-inner">${pageHierarchy()}</div></div>',
    '<div class="page"><div class="page-inner">${pageActionsSignoff()}</div></div>',
  ].join();

  return '''
<!doctype html>
<html lang="en" dir="ltr">
<head>
<meta charset="utf-8">
<style>$css</style>
</head>
<body>$pages</body>
</html>
''';
}
